package cache

import (
	"context"
	"time"

	"github.com/ThisIsTheOldGuard/payship-core/internal/domain"
)

// NoopCache представляет собой заглушку (Null Object) для интерфейса Cache.
//
// Используется в качестве fallback-реализации при недоступности Redis на этапе
// запуска приложения. Позволяет сервису продолжать работу в режиме graceful
// degradation, перенаправляя все запросы на чтение напрямую в базу данных,
// при этом сохраняя совместимость с интерфейсом Cache и не вызывая паник.
type NoopCache struct{}

// Get имитирует промах кэша (cache miss) при отключенном кэшировании.
//
// Параметры:
//   - ctx: контекст для отмены операции или установки таймаута.
//   - key: уникальный идентификатор запрашиваемого значения.
//
// Возвращает:
//   - string: пустая строка.
//   - error: domain.ErrCacheDisabled, сигнализирующий вышестоящему слою
//     о необходимости получить данные из основного хранилища (БД).
func (n *NoopCache) Get(ctx context.Context, key string) (string, error) {
	return "", domain.ErrCacheDisabled
}

// Set игнорирует попытку записи в кэш.
//
// Параметры:
//   - ctx: контекст для отмены операции или установки таймаута.
//   - key: уникальный идентификатор значения (игнорируется).
//   - value: сохраняемое строковое значение (игнорируется).
//   - exp: время жизни значения (игнорируется).
//
// Возвращает:
//   - error: всегда nil, так как операция намеренно не выполняет никаких действий
//     и не должна блокировать основной поток выполнения.
func (n *NoopCache) Set(ctx context.Context, key, value string, exp time.Duration) error {
	return nil
}

// Delete игнорирует попытку удаления ключа из кэша.
//
// Параметры:
//   - ctx: контекст для отмены операции или установки таймаута.
//   - key: уникальный идентификатор удаляемого значения (игнорируется).
//
// Возвращает:
//   - error: всегда nil, так как операция намеренно не выполняет никаких действий.
func (n *NoopCache) Delete(ctx context.Context, key string) error {
	return nil
}

// Ping сообщает о недоступности инфраструктуры кэширования.
//
// Параметры:
//   - ctx: контекст для отмены операции или установки таймаута.
//
// Возвращает:
//   - error: domain.ErrCacheDisabled, указывая на то, что кэш неактивен.
func (n *NoopCache) Ping(ctx context.Context) error {
	return domain.ErrCacheDisabled
}
